def set_age(person, age):
    if age < 0:
        raise ValueError("Age cannot be negative")
    person["age"] = age
    return person

def total(values):
    t = 0
    for v in values:
        if v is not None:
            t += v
    return t

def withdraw(self, amount):
    if self.balance - amount < 0:
        return False
    self.balance -= amount
    return True

def apply_code(total_paise, code):
    """Return the total after applying a discount code."""
    from config import DISCOUNT_CODES
    if code in DISCOUNT_CODES:
        return total_paise * (1 - DISCOUNT_CODES[code] / 100)
    else:
        return total_paise

